import {cityById} from '../data/cities.js';
import {careerById} from '../data/careers.js';
import {educationNames,labels,money} from '../data/catalog.js';
import {netWorth,totalDebt} from './finance.js';
const percent=n=>Math.round(Math.max(0,Math.min(100,n)));
export function aspirationProgress(s){const levels=s.careerHistory.reduce((n,c)=>Math.max(n,c.highest),0);const happy=s.totals.happiness/Math.max(1,s.totals.years);const core=Object.values(s.hobbies).sort((a,b)=>b-a)[0];return percent(({'财富自由':netWorth(s)/50000,'家庭幸福':(s.partner?.relationship??0)*.8+s.children.length*10,'成为名人':s.stats.reputation/3,'事业成功':levels*20,'行业顶尖':levels*20,'稳定生活':(s.debt===0?30:0)+(s.properties.length?30:0)+(s.retired||s.career?30:0),'自由生活':happy*.6+(s.debt===0?30:0),'做喜欢的事情':core,'帮助别人':s.counts.help*15,'暂时没有明确目标':happy})[s.aspiration]??0);}
export function titles(s){const a=[];if(s.tags.includes('世界冠军'))a.push('世界冠军');if(s.tags.includes('百万粉丝'))a.push('顶流网红');if(s.career==='lawyer'&&s.careerLevel>=4)a.push('一代名律');if(s.birthCity==='nantong'&&s.company>1000000)a.push('南通船王');if(s.counts.careerChanges>=3)a.push('跨界之王');if(s.counts.moves>=5)a.push('一生漂泊');else if(s.counts.moves>=2)a.push('跨城奋斗者');if(s.counts.moves&&s.city===s.birthCity)a.push('落叶归根');if(s.cityHistory.filter(c=>c.city==='beijing').reduce((n,c)=>n+(c.endAge??s.age)-c.startAge,0)>=30&&s.birthCity!=='beijing')a.push('北漂三十年');if(s.tags.includes('主动停止赌博')&&s.debt===0)a.push('浪子回头');if(s.counts.startups>=2&&s.counts.gambles>=3)a.push('创业赌徒');if(s.totals.income>10000000&&s.counts.startups===0)a.push('打工皇帝');if(!a.length)a.push(s.totals.happiness/Math.max(1,s.totals.years)>60?'普通但幸福的一生':'平平淡淡才是真');return a;}
export function getReport(s){const avg=(key)=>s.totals[key]/Math.max(1,s.totals.years);const highest=s.careerHistory.reduce((m,c)=>c.highest>m.highest?c:m,{highest:-1,career:null});return {
 title:titles(s),
 dimensions:[['财富',netWorth(s)>3000000?'宽裕':netWorth(s)>0?'有所积累':'仍有负担'],['事业',highest.highest>=4?'走得很远':highest.highest>=1?'逐步积累':'探索过自己的方向'],['家庭',s.partner?.relationship>60?'有人相伴':'有过牵挂'],['健康',avg('health')>60?'大体安康':'经历过不易'],['快乐',avg('happiness')>60?'快乐常在':'悲喜交织'],['愿望完成度',aspirationProgress(s)+'%']],
 sections:[
 {title:'这一生',rows:[['姓名',s.name],['性别',s.gender],['出生',s.birthYear+'年 · '+cityById(s.birthCity).name],['离世',s.dead?(s.birthYear+s.age)+'年 · '+cityById(s.city).name:'人生仍在继续'],['享年',s.age+'岁'],['人生终点',s.deathReason||'尚未结束']]},
 {title:'教育与校园',rows:[['最高学历',educationNames[s.education]],['重要经历',s.schoolHistory.map(x=>x.age+'岁 · '+x.text).join('；')||'还没有学校经历'],['社团',s.clubs.join('、')||'未加入社团']]},
 {title:'城市足迹',rows:[...s.cityHistory.map(c=>[cityById(c.city).name,`${c.startAge}～${c.endAge??s.age}岁 · ${(c.endAge??s.age)-c.startAge}年 · ${c.reason}`]),['搬家次数',s.counts.moves+'次']]},
 {title:'职业生涯',rows:[...s.careerHistory.map(c=>[careerById(c.career).name,`${c.startAge}～${c.endAge??s.age}岁 · 最高${careerById(c.career).levels[c.highest]}`]),['最终职业',careerById(s.career)?.name??'无正式职业'],['最高职业等级',highest.career?careerById(highest.career).levels[highest.highest]:'尚无'],['转行次数',s.counts.careerChanges+'次']]},
 {title:'财富',rows:[['累计收入',money(s.totals.income)],['财富峰值',money(s.totals.peak)],['最终净资产',money(netWorth(s))],['房产',s.properties.map(p=>cityById(p.city).name+' · '+money(p.value)).join('；')||'无房产'],['负债',money(totalDebt(s))],['创业次数',s.counts.startups+'次']]},
 {title:'家人',rows:[['感情状态',s.relationshipStatus],['伴侣',s.partner?.name??'暂无伴侣'],['子女',s.children.map(c=>c.name+' · '+c.age+'岁').join('；')||'无子女'],...s.parents.map(p=>[p.role,p.name+' · '+p.age+'岁 · '+(p.alive?'健在':'已故')])]},
 {title:'喜欢过的事',rows:[['核心爱好',Object.entries(s.hobbies).sort((a,b)=>b[1]-a[1]).slice(0,4).map(([k,v])=>k+' '+Math.round(v)).join('、')],['人格倾向',Object.entries(s.personality).filter(([,v])=>v>=10).map(([k])=>labels[k]).join('、')||'仍保有多种可能'],['人生愿望',s.aspiration],['愿望完成度',aspirationProgress(s)+'%']]},
 {title:'命运留下的痕迹',rows:[['赌博经历',s.counts.gambles+'次参与 · '+s.counts.wins+'次赢 · '+s.counts.losses+'次亏损'],['长期标签',s.tags.join('、')||'没有特殊标签'],['社会履历',s.socialHistory.map(h=>h.age+'岁 · '+h.text).join('；')||'没有特别记录'],['重大成功',s.tags.filter(t=>/成功|冠军|爆款|百万/.test(t)).join('、')||'那些小事同样值得记住'],['重大失败',s.tags.filter(t=>/失败|负债|伤病|破产|争议/.test(t)).join('、')||'没有留下此类记录']]}
 ]};}
